import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-perfeccion', 'A',
 [dict(t=1685, e=1738, titulo='Bueno, excelente y perfecto', txt='Ahora, la perfección tiene niveles. Usted sabe que en la tierra está lo bueno, pero también está lo excelente. Dicen que lo bueno mata lo excelente, pero esto es en el mundo. Ahora, cuando ya analizamos las cosas de la tierra y lo celestial, lo espiritual, nos damos cuenta de que lo excelente también se queda, hermano, porque usted puede ser excelente, pero lo que usted tiene que hacer es perfecto. Entonces, miramos tres niveles aquí: bueno, excelente y perfecto.'),
  dict(t=3701, e=3741, titulo='La perfección es un camino', txt='Tienes que ver qué es lo bueno, aceptable y perfecto, para que andes en la voluntad de Dios. Salmo 101:2: «Entenderé el camino de la perfección». Volvemos a lo mismo: la perfección es un camino. Si no seguimos ese camino, no vamos a ser perfeccionados. Por eso le puse ese camino como una escalera que iba hasta el cielo, porque esa es la perfección para que nosotros miremos a Dios. ¿Cuántos están contentos por eso?'),
  dict(t=4328, e=4392, titulo='El camino de la perfección', txt='Si somos perfeccionados, vamos a ver al Señor definitivamente. Así que yo le invito a que usted y yo nos bendiga el Señor, para que usted agarre el camino de la perfección, y que solucione sus problemas, y que le arranque sus ataduras, que lo purifique, que lo limpie. Dice la Palabra que el que ama la venida del Señor se purifica. Así mismo, yo sé que nos falta, pero no es imposible. Si Dios te dijo que te va a perfeccionar, yo lo creo. Y si yo lo creo, eso es lo que voy a administrar esta noche, para que todo aquel que abra su corazón empiece el camino de la perfección.')],
 [dict(t=1515, txt='Lo que usted no terminó, Dios lo va a terminar en usted.'),
  dict(t=3487, txt='«Anda delante de mí y sé perfecto». Dios te va a hablar.'),
  dict(t=4653, txt='Estás cayendo en las manos de un Dios que te ama y que perfecciona tu vida a lo máximo.')],
 ['Si Dios hace lo imposible y nosotros lo posible, ¿qué es lo «posible» que te toca hacer hoy en tu camino hacia la perfección?',
  'La perfección tiene niveles —bueno, excelente, perfecto—: ¿en qué área te has conformado con lo bueno o lo excelente?',
  '¿Qué ataduras o inmundicias le pedirías a Dios que te arranque y te purifique esta semana?'],
 inicio=1285)
